export const EXAMPLE_REGISTRY: Readonly<Record<string, readonly ExampleRecord[]>> = EXAMPLE_RECORDS.reduce<Record<string, ExampleRecord[]>>(
  (registry, record) => {
    (registry[record.slug] ??= []).push(record);
    return registry;
  },
  {},
);

export const EXAMPLE_SOURCE: Readonly<Record<string, Readonly<Record<string, string>>>> = Object.fromEntries(
  Object.entries(EXAMPLE_REGISTRY).map(([slug, entries]) => [
    slug,
    Object.fromEntries(entries.map((entry) => [entry.id, entry.source])),
  ]),
);
